"use client";
// Independently implemented ROC primitive.
export { LiquidButton } from "./motion-buttons";
import "./liquid-button.css";

"use client";
import { useEffect, useRef, useState, type ComponentProps, type ReactNode } from "react";
import { Button } from "./button";
import { CountingNumber } from "./counting-number";
import { cn } from "./utils";
import "./motion-buttons.css";

type ButtonProps = ComponentProps<typeof Button>;
export function CopyButton({ text, children = "Copy", ...props }: ButtonProps & { text: string }) {
  const [status, setStatus] = useState("");
  const timer = useRef<ReturnType<typeof setTimeout> | null>(null);
  useEffect(() => () => { if (timer.current) clearTimeout(timer.current); }, []);
  return <span className="roc-copy-button"><Button {...props} onClick={async e => {
    props.onClick?.(e); if (e.defaultPrevented) return;
    try { await navigator.clipboard.writeText(text); setStatus("Copied"); }
    catch { setStatus("Copy unavailable"); }
    if (timer.current) clearTimeout(timer.current);
    timer.current = setTimeout(() => setStatus(""), 2000);
  }}>{children}</Button><span className="roc-copy-feedback" role="status">{status}</span></span>;
}
export function IconButton({ icon, label, ...props }: Omit<ButtonProps, "children" | "aria-label"> & { icon: ReactNode; label: string }) {
  return <Button variant="outline" size="icon" {...props} aria-label={label} title={label}><span aria-hidden="true">{icon}</span></Button>;
}
export function FlipButton({ children, back, className, ...props }: ButtonProps & { back: ReactNode }) {
  const [flipped, setFlipped] = useState(false);
  return <Button {...props} className={cn("roc-flip-button", className)} aria-pressed={flipped} onClick={e => { props.onClick?.(e); if (!e.defaultPrevented) setFlipped(!flipped); }}><span data-flipped={flipped}><span aria-hidden={flipped}>{children}</span><span aria-hidden={!flipped}>{back}</span></span></Button>;
}
export function LiquidButton({ className, ...props }: ButtonProps) { return <Button {...props} className={cn("roc-liquid-button", className)} />; }
export function RippleButton({ className, children, ...props }: ButtonProps) {
  const [pulse, setPulse] = useState(0);
  return <Button {...props} className={cn("roc-ripple-button", className)} onClick={e => { props.onClick?.(e); if (!e.defaultPrevented) setPulse(n => n + 1); }}>{children}{pulse > 0 && <span key={pulse} aria-hidden="true" className="roc-button-ripple" />}</Button>;
}
export function ThemeTogglerButton({ dark, onDarkChange, ...props }: Omit<ButtonProps, "children"> & { dark: boolean; onDarkChange: (dark: boolean) => void }) {
  return <Button variant="outline" {...props} aria-pressed={dark} aria-label={dark ? "Use light appearance" : "Use dark appearance"} onClick={e => { props.onClick?.(e); if (!e.defaultPrevented) onDarkChange(!dark); }}><span aria-hidden="true">{dark ? "☾" : "☀"}</span><span>{dark ? "Dark" : "Light"}</span></Button>;
}
export function GithubStars({ count, label = "Stars" }: { count: number; label?: string }) { return <span className="roc-ui roc-github-stars"><span aria-hidden="true">☆</span><CountingNumber value={count} /><span>{label}</span></span>; }
export function GithubStarsButton({ count, href, children = "View repository" }: { count: number; href: string; children?: ReactNode }) {
  return <Button variant="outline" asChild><a href={href} target="_blank" rel="noreferrer">{children}<GithubStars count={count} label="" /></a></Button>;
}

// Adapted from shadcn/ui (MIT). See SHADCN-LICENSE.txt and upstream provenance.
import * as React from "react";
import { cva, type VariantProps } from "class-variance-authority";
import { cn } from "./utils";
import { Pressable } from "./primitive-pressable";

const buttonVariants = cva("roc-ui roc-ui-button", {
  variants: {
    variant: {
      default: "roc-ui-button-variant-default",
      destructive: "roc-ui-button-variant-destructive",
      outline: "roc-ui-button-variant-outline",
      secondary: "roc-ui-button-variant-secondary",
      ghost: "roc-ui-button-variant-ghost",
      link: "roc-ui-button-variant-link",
    },
    size: {
      default: "roc-ui-button-size-default",
      xs: "roc-ui-button-size-xs",
      sm: "roc-ui-button-size-sm",
      lg: "roc-ui-button-size-lg",
      icon: "roc-ui-button-size-icon",
      "icon-xs": "roc-ui-button-size-icon-xs",
      "icon-sm": "roc-ui-button-size-icon-sm",
      "icon-lg": "roc-ui-button-size-icon-lg",
    },
  },
  defaultVariants: {
    variant: "default",
    size: "default",
  },
});

function Button({
  className,
  variant = "default",
  size = "default",
  asChild = false,
  type,
  children,
  disabled,
  pending = false,
  pendingLabel,
  ...props
}: React.ComponentProps<"button"> &
  VariantProps<typeof buttonVariants> & {
    pending?: boolean;
    pendingLabel?: React.ReactNode;
    asChild?: boolean;
  }) {
  const Comp: React.ElementType = Pressable;

  return (
    <Comp
      asChild={asChild}
      tapScale={disabled || pending ? 1 : 0.97}
      type={asChild ? type : (type ?? "button")}
      data-slot="button"
      data-variant={variant}
      data-size={size}
      className={cn("roc-ui", buttonVariants({ variant, size, className }))}
      {...props}
      disabled={disabled || pending}
      aria-busy={pending || undefined}
    >
      {asChild || pendingLabel === undefined ? (
        children
      ) : (
        <span className="roc-ui-button-label">
          <span
            aria-hidden={pending}
            data-state={pending ? "inactive" : "active"}
          >
            {children}
          </span>
          <span
            aria-hidden={!pending}
            data-state={pending ? "active" : "inactive"}
          >
            {pendingLabel}
          </span>
        </span>
      )}
    </Comp>
  );
}

export { Button, buttonVariants };

import "./button.css";

import { clsx, type ClassValue } from "clsx";
/** Scoped CSS needs no Tailwind runtime or host configuration. */
export function cn(...inputs: ClassValue[]) {
  return clsx(inputs);
}

"use client";
import * as React from "react";
import { Button } from "@base-ui/react/button";
import { Slot } from "./primitive-slot";
import { motion } from "motion/react";
import { useRocReducedMotion, useRocTransition } from "./motion-config";

export function Pressable({ asChild, tapScale = 0.97, children, ...props }:
  React.ComponentProps<"button"> & { asChild?: boolean; tapScale?: number }) {
  const reduce = useRocReducedMotion();
  const transition = useRocTransition("control");
  if (asChild && React.isValidElement(children)) {
    const { disabled, onClick, ...childProps } = props;
    return <Slot.Root {...childProps} aria-disabled={disabled || undefined} onClick={event => {
      if (disabled) { event.preventDefault(); return; }
      onClick?.(event as React.MouseEvent<HTMLButtonElement>);
    }}>{children}</Slot.Root>;
  }
  return <Button {...props} render={<motion.button whileTap={props.disabled || reduce ? undefined : { scale: tapScale }} transition={transition} />}>{children}</Button>;
}

"use client";
// ROC primitive: render the caller's single child with our props merged in (`asChild`).
import * as React from "react";
import { composeRefs } from "./primitive-utils";

type AnyProps = Record<string, any>;

function mergeProps(slotProps: AnyProps, childProps: AnyProps) {
  const merged: AnyProps = { ...childProps };
  for (const key in childProps) {
    const slotValue = slotProps[key];
    const childValue = childProps[key];
    if (/^on[A-Z]/.test(key)) {
      if (slotValue && childValue) {
        merged[key] = (...args: unknown[]) => {
          const result = childValue(...args);
          slotValue(...args);
          return result;
        };
      } else if (slotValue) merged[key] = slotValue;
    } else if (key === "style") {
      merged[key] = { ...slotValue, ...childValue };
    } else if (key === "className") {
      merged[key] = [slotValue, childValue].filter(Boolean).join(" ");
    }
  }
  return { ...slotProps, ...merged };
}

type SlotProps = React.HTMLAttributes<HTMLElement> & {
  children?: React.ReactNode;
  ref?: React.Ref<any>;
};

function Root({ children, ref, ...slotProps }: SlotProps) {
  if (!React.isValidElement(children)) {
    if (React.Children.count(children) > 1) throw new Error("Slot needs one child");
    return null;
  }
  const child = children as React.ReactElement<AnyProps>;
  return React.cloneElement(child, {
    ...mergeProps(slotProps, child.props),
    ref: ref ? composeRefs(ref, child.props.ref) : child.props.ref,
  });
}

export const Slot = { Root };

"use client";
// ROC primitive helpers. Small, dependency-free building blocks.
import * as React from "react";

/** Run the caller's handler first; run ours unless the caller prevented default. */
export function composeEventHandlers<E extends { defaultPrevented: boolean }>(
  original: ((event: E) => void) | undefined,
  ours: ((event: E) => void) | undefined,
) {
  return (event: E) => {
    original?.(event);
    if (!event.defaultPrevented) ours?.(event);
  };
}

type PossibleRef<T> = React.Ref<T> | undefined;

/** Merge refs, forwarding React 19 ref cleanups. */
export function composeRefs<T>(...refs: PossibleRef<T>[]): React.RefCallback<T> {
  return (node) => {
    const cleanups: Array<() => void> = [];
    for (const ref of refs) {
      if (typeof ref === "function") {
        const cleanup = ref(node);
        cleanups.push(
          typeof cleanup === "function" ? cleanup : () => ref(null),
        );
      } else if (ref) {
        (ref as React.RefObject<T | null>).current = node;
        cleanups.push(() => {
          (ref as React.RefObject<T | null>).current = null;
        });
      }
    }
    return () => cleanups.forEach((cleanup) => cleanup());
  };
}

export function useComposedRefs<T>(...refs: PossibleRef<T>[]) {
  // eslint-disable-next-line react-hooks/exhaustive-deps
  return React.useCallback(composeRefs(...refs), refs);
}

export function usePrevious<T>(value: T) {
  const ref = React.useRef({ value, previous: value });
  return React.useMemo(() => {
    if (ref.current.value !== value) {
      ref.current.previous = ref.current.value;
      ref.current.value = value;
    }
    return ref.current.previous;
  }, [value]);
}

"use client";
import { createContext, useContext, useSyncExternalStore, type ReactNode } from "react";
import { MotionConfig, MotionConfigContext, type Transition } from "motion/react";

const Pace = createContext(1);
const Reduction = createContext<"user" | "always" | "never">("user");
let media: MediaQueryList | undefined;
const query = () => media ??= window.matchMedia("(prefers-reduced-motion: reduce)");
const snapshot = () => typeof window !== "undefined" && query().matches;
const serverSnapshot = () => false;
const subscribe = (notify: () => void) => {
  const preference = query();
  preference.addEventListener("change", notify);
  return () => preference.removeEventListener("change", notify);
};
export function RocMotionProvider({ children, pace = 1, reducedMotion = "user" }: {
  children: ReactNode; pace?: number; reducedMotion?: "user" | "always" | "never";
}) {
  return <Reduction.Provider value={reducedMotion}><Pace.Provider value={Math.max(0.1, pace)}><MotionConfig reducedMotion={reducedMotion}>{children}</MotionConfig></Pace.Provider></Reduction.Provider>;
}
export function useRocTransition(kind: "control" | "surface" = "surface"): Transition {
  const pace = useContext(Pace);
  const reduce = useRocReducedMotion();
  if (reduce) return { duration: 0 };
  return kind === "control"
    ? { type: "spring", stiffness: 520 / (pace * pace), damping: 34 / pace }
    : { type: "spring", stiffness: 280 / (pace * pace), damping: 28 / pace };
}
export function useRocReducedMotion() {
  const system = useSyncExternalStore(subscribe, snapshot, serverSnapshot);
  const mode = useContext(Reduction);
  const config = useContext(MotionConfigContext);
  return mode === "always" || config.reducedMotion === "always" || (mode === "user" && system);
}

@import "./ui-base.css";
.roc-ui-button {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  flex-shrink: 0;
  gap: 8px;
  min-height: 36px;
  padding: 8px 15px;
  border: 1px solid transparent;
  border-radius: var(--roc-button-radius, var(--roc-radius-control));
  font-weight: 500;
  cursor: pointer;
  white-space: nowrap;
  text-decoration: none;
  transition:
    background-color var(--roc-motion-quick) ease-out,
    box-shadow var(--roc-motion-quick) ease-out;
}
/* Keep the shared .roc-ui font reset from changing text button height. */
.roc-ui.roc-ui-button {
  line-height: 1.2;
}
.roc-ui-button.roc-ui-button-variant-default {
  background: var(--roc-accent, var(--roc-ink, #252525));
  color: var(--roc-accent-foreground, var(--roc-paper, #fff));
}
.roc-ui-button.roc-ui-button-variant-secondary {
  background: var(--roc-marker, #efefef);
}
.roc-ui-button.roc-ui-button-variant-destructive {
  background: #b73838;
  color: white;
}
.roc-ui-button.roc-ui-button-variant-outline {
  border-color: var(--roc-line, #dedede);
  background: var(--roc-paper, #fff);
}
.roc-ui-button.roc-ui-button-variant-ghost,
.roc-ui-button.roc-ui-button-variant-link {
  background: transparent;
}
.roc-ui-button.roc-ui-button-variant-link {
  text-decoration: underline;
  text-underline-offset: 4px;
}
.roc-ui-button:hover:not(:disabled) {
  box-shadow: inset 0 0 0 100px #80808018;
}
.roc-ui-button.roc-ui-button-size-xs {
  --roc-button-radius: var(--roc-radius-compact);
  min-height: 26px;
  padding: 4px 8px;
  font-size: 11px;
}
.roc-ui-button.roc-ui-button-size-sm {
  --roc-button-radius: var(--roc-radius-compact);
  min-height: 32px;
  padding: 6px 12px;
}
.roc-ui-button.roc-ui-button-size-lg {
  min-height: 42px;
  padding: 11px 22px;
}
.roc-ui-button:is(
  .roc-ui-button-size-icon,
  .roc-ui-button-size-icon-xs,
  .roc-ui-button-size-icon-sm,
  .roc-ui-button-size-icon-lg
) {
  padding: 0;
  width: 36px;
  height: 36px;
}
.roc-ui-button.roc-ui-button-size-icon-xs {
  width: 26px;
  height: 26px;
  min-height: 26px;
}
.roc-ui-button.roc-ui-button-size-icon-sm {
  width: 32px;
  height: 32px;
  min-height: 32px;
}
.roc-ui-button.roc-ui-button-size-icon-lg {
  width: 42px;
  height: 42px;
}
.roc-ui-button[aria-busy="true"] {
  cursor: progress;
}

.roc-ui-button-label {
  display: inline-grid;
  align-items: center;
}
.roc-ui-button-label > span {
  grid-area: 1 / 1;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
}
/* Pending swaps the label in place: the outgoing text lifts away blurred while
   the incoming text settles up from below. */
.roc-ui-button-label > span {
  transition:
    opacity var(--roc-motion-quick) ease-in-out,
    transform var(--roc-motion-quick) ease-in-out,
    filter var(--roc-motion-quick) ease-in-out;
}
.roc-ui-button-label > span[data-state="inactive"] {
  opacity: 0;
  filter: blur(var(--roc-motion-blur));
  pointer-events: none;
}
.roc-ui-button-label > span:first-child[data-state="inactive"] {
  transform: translateY(-4px);
}
.roc-ui-button-label > span:last-child[data-state="inactive"] {
  transform: translateY(4px);
}
@media (prefers-reduced-motion: reduce) {
  .roc-ui-button-label > span {
    transition: none;
  }
}

@import "./animation.css";
@import "./corners.css";
@import "./responsive.css";
/* Shared ROC foundations. No global reset or host stylesheet required. */
.roc-ui {
  box-sizing: border-box;
  font: inherit;
  font-size: 13px;
  color: var(--roc-ink, #252525);
}
.roc-ui *,
.roc-ui *::before,
.roc-ui *::after {
  box-sizing: border-box;
}
.roc-ui:focus-visible,
.roc-shadcn:focus-visible {
  outline: none;
  /* Draw the focus border inward, without changing the control's dimensions.
     Keep it visible when component hover or utility styles set box-shadow. */
  box-shadow: inset 0 0 0 2px var(--roc-focus, #737373) !important;
}
.roc-shadcn:focus {
  /* Imported utilities must not add an outer focus ring or its offset. */
  --roc-sh-tw-ring-shadow: 0 0 #0000 !important;
  --roc-sh-tw-ring-offset-shadow: 0 0 #0000 !important;
}
@media (forced-colors: active) {
  .roc-ui:focus-visible,
  .roc-shadcn:focus-visible {
    outline: 2px solid Highlight;
    outline-offset: -2px;
  }
}
.roc-ui:disabled,
.roc-ui[data-disabled] {
  opacity: 0.45;
  cursor: not-allowed;
}
/* Micro-motion scale, adapted from transitions.dev. Override on `.roc-ui`. */
:where(.roc-ui, .roc-shadcn) {
  --roc-motion-quick: 150ms;
  --roc-motion-fast: 250ms;
  --roc-motion-medium: 350ms;
  --roc-motion-ease: cubic-bezier(0.22, 1, 0.36, 1);
  --roc-motion-bounce: cubic-bezier(0.34, 1.36, 0.64, 1);
  --roc-motion-blur: 2px;
}
.roc-ui-icon,
.roc-ui > svg {
  width: 16px;
  height: 16px;
  flex-shrink: 0;
  pointer-events: none;
}
.roc-ui-sr-only {
  position: absolute;
  width: 1px;
  height: 1px;
  padding: 0;
  margin: -1px;
  overflow: hidden;
  clip: rect(0, 0, 0, 0);
  white-space: nowrap;
  border: 0;
}
/* Surfaces scale in from their anchor and settle back more quietly on exit. */
@keyframes roc-ui-pop-in {
  from {
    opacity: 0;
    transform: scale(var(--roc-pop-scale, 0.97));
  }
}
@keyframes roc-ui-pop-out {
  to {
    opacity: 0;
    transform: scale(var(--roc-pop-scale-out, 0.99));
  }
}
/* Side panels slide from their own edge; set --roc-slide-x / --roc-slide-y. */
@keyframes roc-ui-slide-in {
  from {
    translate: var(--roc-slide-x, 0) var(--roc-slide-y, 0);
  }
}
@keyframes roc-ui-slide-out {
  to {
    translate: var(--roc-slide-x, 0) var(--roc-slide-y, 0);
  }
}
/* A swapped icon arrives small and blurred; messages settle up from below. */
@keyframes roc-ui-icon-in {
  from {
    opacity: 0;
    scale: 0.25;
    filter: blur(var(--roc-motion-blur));
  }
}
@keyframes roc-ui-rise-in {
  from {
    opacity: 0;
    translate: 0 4px;
    filter: blur(var(--roc-motion-blur));
  }
}
/* Invalid fields answer with one short horizontal shake. */
@keyframes roc-ui-shake {
  20% {
    translate: 6px 0;
  }
  50% {
    translate: -6px 0;
  }
  78% {
    translate: 4px 0;
  }
}
@keyframes roc-ui-dismiss {
  from {
    opacity: 1;
  }
  to {
    opacity: 0;
  }
}
@media (prefers-reduced-motion: reduce) {
  .roc-ui,
  .roc-ui::before,
  .roc-ui::after {
    transition-duration: 0s !important;
    animation-duration: 0.01ms !important;
  }
}

/* ROC owns motion; Base UI owns interaction and portal presence. */
/* These parts use spring positions, so a CSS transition would lag the pointer. */
.roc-ui[data-slot="slider-thumb"],
.roc-ui[data-slot="slider-range"] {
  transition-property: background-color, border-color, box-shadow;
}
/* Static content stays still; interactive surfaces respond to state changes. */
:where(.roc-ui, .roc-shadcn):is(
  [data-slot="card"], [data-slot="item"], [data-slot="attachment"],
  [data-slot="table-row"], [data-slot="sidebar-menu-button"]
) {
  transition: background-color 150ms ease-out, border-color 150ms ease-out,
    box-shadow 150ms ease-out;
}
@media (prefers-reduced-motion: reduce) {
  :where(.roc-ui, .roc-shadcn):is(
    [data-slot="card"], [data-slot="item"], [data-slot="attachment"],
    [data-slot="table-row"], [data-slot="sidebar-menu-button"]
  ) { transition: none; }
}

/* Smooth squircle corners, following the visual treatment at https://corne.rs/.
   Native corner shaping keeps borders, shadows and overflowing content intact.
   Browsers without support retain the existing border-radius fallback. */
:where(
  [class^="roc-"],
  [class*=" roc-"],
  [class^="roc-"] *,
  [class*=" roc-"] *
) {
  /* ROC limits by role, informed by Apple's compact-control and surface guidance.
     These are ROC values, not platform-prescribed dimensions. Zero stays square. */
  --roc-radius-compact: min(var(--roc-radius, 9px), 8px);
  --roc-radius-control: min(var(--roc-radius, 9px), 10px);
  --roc-radius-popup: min(var(--roc-radius, 9px), 12px);
  --roc-radius-surface: min(var(--roc-radius, 12px), 20px);
}
@supports (corner-shape: squircle) {
  :where(
    [class^="roc-"],
    [class*=" roc-"],
    [class^="roc-"] *,
    [class*=" roc-"] *
  ) {
    corner-shape: var(--roc-corner-shape, squircle);
  }
}

/* Shared viewport constraints for portalled controls, including standalone consumers. */
:is(.roc-ui, .roc-shadcn)[data-slot]:is(
  [data-slot="popover-content"],
  [data-slot="hover-card-content"],
  [data-slot="tooltip-content"],
  [data-slot="select-content"],
  [data-slot="combobox-content"],
  [data-slot="dropdown-menu-content"],
  [data-slot="dropdown-menu-sub-content"],
  [data-slot="context-menu-content"],
  [data-slot="context-menu-sub-content"],
  [data-slot="menubar-content"],
  [data-slot="menubar-sub-content"]
) {
  max-inline-size: min(var(--available-width, calc(100vw - 24px)), calc(100vw - 24px));
  max-block-size: min(var(--available-height, calc(100dvh - 24px)), calc(100dvh - 24px));
  overflow: auto;
  overflow-wrap: anywhere;
  overscroll-behavior: contain;
}
@media (max-width: 640px), (pointer: coarse) {
  .roc-ui.roc-ui-button[data-slot],
  .roc-ui[data-slot="native-select"],
  .roc-shadcn[data-slot="select-trigger"] {
    min-height: 44px;
  }
  .roc-ui.roc-ui-button[data-size^="icon"] {
    width: 44px;
    height: 44px;
  }
  .roc-ui[data-slot="input"],
  .roc-ui[data-slot="textarea"],
  .roc-shadcn[data-slot="input-group-control"] {
    font-size: 16px;
  }
  .roc-ui[data-slot="input"],
  .roc-shadcn[data-slot="input-group"],
  .roc-ui[data-slot="slider"] {
    min-height: 44px;
  }
  .roc-shadcn[data-slot="input-group"] [data-slot="input-group-control"] {
    min-height: 42px;
  }
  .roc-sidebar-link,
  .roc-ui[data-slot="tabs-trigger"],
  .roc-ui[data-slot="toggle"],
  .roc-shadcn[data-slot="select-item"],
  .roc-shadcn[data-slot="combobox-item"] {
    min-height: 44px;
  }
  .roc-ui[data-slot="dropdown-menu-item"],
  .roc-ui[data-slot="dropdown-menu-checkbox-item"],
  .roc-ui[data-slot="dropdown-menu-radio-item"],
  .roc-shadcn[data-slot="context-menu-item"],
  .roc-shadcn[data-slot="menubar-item"] {
    min-height: 44px;
  }
}

"use client";
// Independently implemented ROC primitive.
export { CountingNumber } from "./motion-text";
import "./counting-number.css";

"use client";
import { useEffect, useRef, useState, type ComponentProps } from "react";
import { AnimatePresence, animate, motion, useMotionValue } from "motion/react";
import { useRocReducedMotion, useRocTransition } from "./motion-config";
import { cn } from "./utils";
import "./motion-text.css";

type TextKind = "gradient" | "highlight" | "morphing" | "rolling" | "rotating" | "shimmering" | "sliding" | "splitting" | "swapping";
export type TextMotionProps = Omit<ComponentProps<"span">, "children"> & { children: string; active?: boolean };
export function MotionText({ children, active = true, effect, className, ...props }: TextMotionProps & { effect: TextKind }) {
  const reduce = useRocReducedMotion(), transition = useRocTransition();
  const split = ["splitting", "rolling"].includes(effect);
  return <span {...props} className={cn("roc-ui roc-motion-text", className)} data-text-effect={effect} data-active={active && !reduce}>
    <span className="roc-ui-sr-only">{children}</span>
    <span aria-hidden="true" className="roc-text-visual">
      {split ? Array.from(children).map((char, i) => <motion.span className="roc-text-letter" key={i} initial={false}
        animate={{ y: active || reduce ? 0 : 16, opacity: active || reduce ? 1 : 0.35, rotateX: effect === "rolling" && !active && !reduce ? 80 : 0 }}
        transition={{ ...transition, delay: reduce ? 0 : i * 0.018 }}>{char === " " ? "\u00a0" : char}</motion.span>) :
        <AnimatePresence mode="popLayout" initial={false}>
          <motion.span key={effect === "sliding" ? `${children}-${active}` : children} initial={reduce ? false : { opacity: 0, y: (effect === "swapping" || effect === "sliding") ? 14 : 0, rotateX: effect === "rotating" ? -80 : 0, filter: effect === "morphing" ? "blur(8px)" : "blur(0px)" }}
            animate={{ opacity: 1, y: 0, rotateX: 0, filter: "blur(0px)" }} exit={{ opacity: 0 }} transition={transition}>{children}</motion.span>
        </AnimatePresence>}
    </span>
  </span>;
}
export function GradientText(props: TextMotionProps) { return <MotionText {...props} effect="gradient" />; }
export function HighlightText(props: TextMotionProps) { return <MotionText {...props} effect="highlight" />; }
export function MorphingText(props: TextMotionProps) { return <MotionText {...props} effect="morphing" />; }
export function RollingText(props: TextMotionProps) { return <MotionText {...props} effect="rolling" />; }
export function RotatingText(props: TextMotionProps) { return <MotionText {...props} effect="rotating" />; }
export function ShimmeringText(props: TextMotionProps) { return <MotionText {...props} effect="shimmering" />; }
export function SlidingText(props: TextMotionProps) { return <MotionText {...props} effect="sliding" />; }
export function SplittingText(props: TextMotionProps) { return <MotionText {...props} effect="splitting" />; }
export function SwappingText(props: TextMotionProps) { return <MotionText {...props} effect="swapping" />; }
export function TypingText({ children, active = true, speed = 45, className, ...props }: TextMotionProps & { speed?: number }) {
  const reduce = useRocReducedMotion();
  const characters = Array.from(children);
  const [length, setLength] = useState(characters.length);
  useEffect(() => {
    if (!active || reduce) { setLength(Array.from(children).length); return; }
    setLength(0);
    const timer = setInterval(() => setLength(n => {
      if (n + 1 >= Array.from(children).length) clearInterval(timer);
      return Math.min(n + 1, Array.from(children).length);
    }), Math.max(16, speed));
    return () => clearInterval(timer);
  }, [children, active, speed, reduce]);
  return <span {...props} className={cn("roc-ui roc-typing-text", className)}><span className="roc-ui-sr-only">{children}</span><span aria-hidden="true" className="roc-typing-reserve">{children}</span><span aria-hidden="true" className="roc-typing-visible">{characters.slice(0, length).join("")}</span></span>;
}
export type NumberMotionProps = Omit<ComponentProps<"span">, "children"> & { value: number; decimals?: number; duration?: number };
export function CountingNumber({ value, decimals = 0, duration = 0.65, className, ...props }: NumberMotionProps) {
  const reduce = useRocReducedMotion(), number = useMotionValue(value), visible = useRef<HTMLSpanElement>(null);
  const places = Math.min(6, Math.max(0, decimals));
  const initialText = useRef(value.toFixed(places));
  useEffect(() => {
    const render = (n: number) => { if (visible.current) visible.current.textContent = n.toFixed(places); };
    render(number.get());
    const off = number.on("change", render);
    const control = animate(number, value, { duration: reduce ? 0 : Math.max(0, duration), ease: "easeOut" });
    return () => { off(); control.stop(); };
  }, [value, places, duration, number, reduce]);
  return <span {...props} className={cn("roc-ui roc-motion-number", className)}><span className="roc-ui-sr-only">{value.toFixed(places)}</span><span aria-hidden="true" ref={visible}>{initialText.current}</span></span>;
}
export function ScrollingNumber({ value, decimals = 0, className, ...props }: NumberMotionProps) {
  const transition = useRocTransition("control");
  const text = value.toFixed(Math.min(6, Math.max(0, decimals)));
  return <span {...props} className={cn("roc-ui roc-motion-number", className)}><span className="roc-ui-sr-only">{text}</span><span aria-hidden="true" className="roc-number-digits">{Array.from(text).map((digit, i) => /\d/.test(digit) ? <span key={text.length - i} className="roc-number-window"><motion.span initial={false} animate={{ y: `${Number(digit) * -10}%` }} transition={transition}>{Array.from({ length: 10 }, (_, n) => <span key={n}>{n}</span>)}</motion.span></span> : <span key={text.length - i}>{digit}</span>)}</span></span>;
}
export function SlidingNumber({ value, decimals = 0, className, ...props }: NumberMotionProps) {
  const reduce = useRocReducedMotion(), transition = useRocTransition();
  const text = value.toFixed(Math.min(6, Math.max(0, decimals)));
  return <span {...props} className={cn("roc-ui roc-motion-number roc-number-slide", className)}><span className="roc-ui-sr-only">{text}</span><span aria-hidden="true"><AnimatePresence initial={false} mode="popLayout"><motion.span key={text} initial={{ y: reduce ? 0 : "100%", opacity: 0 }} animate={{ y: 0, opacity: 1 }} exit={{ y: reduce ? 0 : "-100%", opacity: 0 }} transition={transition}>{text}</motion.span></AnimatePresence></span></span>;
}

@import "./ui-base.css";
